const supabaseUrl = String.fromEnvironment('SUPABASE_URL', defaultValue: 'https://rrtahdvdcczbxzsukjgl.supabase.co');
const supabaseAnonKey = String.fromEnvironment('SUPABASE_ANON_KEY', defaultValue: 'sb_publishable_oGfA8TS3ml1GR58UD_-WSg_IUQpC4lY');
const unityGameId = '800438578';
const rewardedPlacement = 'BP_Rewarded_Android';
const bannerPlacement = 'BP_Banner_Android';
const overlayChannel = MethodChannel('tweetflow/overlay_permission');

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  if (!supabaseUrl.contains('YOUR_PROJECT') && !supabaseAnonKey.contains('YOUR_SUPABASE')) {
    await Supabase.initialize(url: supabaseUrl, anonKey: supabaseAnonKey);
  }
  runApp(const TweetFlowApp());
}

class TweetFlowApp extends StatelessWidget {
  const TweetFlowApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    title: 'TweetFlow AI', debugShowCheckedModeBanner: false,
    theme: ThemeData(colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xFF635BFF), brightness: Brightness.light), useMaterial3: true, scaffoldBackgroundColor: const Color(0xFFF7F8FC)),
    home: supabaseReady ? const AuthGate() : const SetupScreen(),
  );
}
bool get supabaseReady => !supabaseUrl.contains('YOUR_PROJECT') && !supabaseAnonKey.contains('YOUR_SUPABASE');

class SetupScreen extends StatelessWidget {
  const SetupScreen({super.key});
  @override Widget build(BuildContext context) => Scaffold(body: Center(child: Padding(padding: const EdgeInsets.all(28), child: Column(mainAxisSize: MainAxisSize.min, children: [const Icon(Icons.bolt, size: 54, color: Color(0xFF635BFF)), const SizedBox(height: 16), const Text('Connect your Supabase project', style: TextStyle(fontSize: 22, fontWeight: FontWeight.bold)), const SizedBox(height: 10), const Text('Before running the app, add SUPABASE_URL and SUPABASE_ANON_KEY in Codemagic environment variables or pass them with --dart-define.', textAlign: TextAlign.center), const SizedBox(height: 18), const Text('No private AI provider key belongs in this APK.', style: TextStyle(fontWeight: FontWeight.w600))]))));
}

class AuthGate extends StatelessWidget {
  const AuthGate({super.key});
  @override Widget build(BuildContext context) => StreamBuilder<AuthState>(stream: Supabase.instance.client.auth.onAuthStateChange, builder: (context, snapshot) { final user = Supabase.instance.client.auth.currentUser; return user == null ? const LoginScreen() : const HomeScreen(); });
}

class LoginScreen extends StatefulWidget { const LoginScreen({super.key}); @override State<LoginScreen> createState() => _LoginScreenState(); }
class _LoginScreenState extends State<LoginScreen> {
  final email = TextEditingController(), password = TextEditingController(); bool register = false, busy = false; String? error;
  Future<void> submit() async { setState(() { busy = true; error = null; }); try { if (register) { await Supabase.instance.client.auth.signUp(email: email.text.trim(), password: password.text); } else { await Supabase.instance.client.auth.signInWithPassword(email: email.text.trim(), password: password.text); } } on AuthException catch(e) { error = e.message; } catch(e) { error = e.toString(); } if(mounted) setState(() => busy = false); }
  @override Widget build(BuildContext context) => Scaffold(body: Center(child: SingleChildScrollView(padding: const EdgeInsets.all(24), child: ConstrainedBox(constraints: const BoxConstraints(maxWidth: 440), child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [const Icon(Icons.bolt, size: 58, color: Color(0xFF635BFF)), const SizedBox(height: 12), const Text('TweetFlow AI', textAlign: TextAlign.center, style: TextStyle(fontSize: 30, fontWeight: FontWeight.w800)), const Text('Your daily tweet studio', textAlign: TextAlign.center), const SizedBox(height: 32), TextField(controller: email, keyboardType: TextInputType.emailAddress, decoration: const InputDecoration(labelText: 'Email', prefixIcon: Icon(Icons.email_outlined), border: OutlineInputBorder())), const SizedBox(height: 12), TextField(controller: password, obscureText: true, decoration: const InputDecoration(labelText: 'Password', prefixIcon: Icon(Icons.lock_outline), border: OutlineInputBorder())), if(error != null) Padding(padding: const EdgeInsets.only(top: 12), child: Text(error!, style: const TextStyle(color: Colors.red))), const SizedBox(height: 18), FilledButton(onPressed: busy ? null : submit, child: Text(busy ? 'Please wait…' : register ? 'Create account' : 'Log in')), TextButton(onPressed: () => setState(() => register = !register), child: Text(register ? 'Already have an account? Log in' : 'New here? Create an account')), TextButton(onPressed: () async { if(email.text.trim().isNotEmpty) { await Supabase.instance.client.auth.resetPasswordForEmail(email.text.trim()); if(mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Password reset email requested.'))); } }, child: const Text('Forgot password?'))])))));
}

class Topic { final String title, description; Topic(this.title, this.description); factory Topic.fromMap(Map<String,dynamic> m) => Topic(m['title'] ?? '', m['description'] ?? ''); }

class HomeScreen extends StatefulWidget { const HomeScreen({super.key}); @override State<HomeScreen> createState() => _HomeScreenState(); }
